// Request Ride Action - שולח בקשת נסיעה לסדרן וממתין לאישורו לפני חשיפת טלפון הלקוח
function requestRide(rideId, buttonElement) {
    if (buttonElement.disabled) return;

    buttonElement.classList.add('btn-pulse');
    setTimeout(() => buttonElement.classList.remove('btn-pulse'), 300);

    const data = loadAppData();
    const driverName = data.currentDriverName;
    const ride = data.availableRides.find(r => r.id === rideId);
    const alreadyRequested = data.rideRequests.find(req => req.rideId === rideId && req.driverName === driverName && req.status !== 'rejected');

    if (!alreadyRequested && ride && ride.status !== 'assigned' && ride.status !== 'closed') {
        const record = {
            id: 'req-' + Date.now(),
            rideId,
            driverName,
            status: 'pending',
            timestamp: new Date().toLocaleString('he-IL'),
            createdAtMs: Date.now(),
            contactedAt: null,
            closedAt: null,
            rejectionReason: null
        };
        data.rideRequests.push(record);
        currentEarned += ride.price;
        renderGoalUI();
        saveAppData(data);

        // כתיבה אטומית ייעודית לשרת (append, לא דריסת /api/state הכללי) - מונעת מרוץ
        // שבו שני נהגים ששולחים בקשה כמעט בו-זמנית ידרסו זה את בקשתו של זה (ר' app.py)
        fetch('/api/ride-requests', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(record)
        }).catch(() => {});
    }

    renderAvailableRides();
}

function saveAccountSettings(e) {
    e.preventDefault();
    const newName = document.getElementById('driverNameInput').value;
    if (!newName) return;
    const submitBtn = e.target.querySelector('button[type="submit"]');
    runAccountSaveAction(submitBtn, () => {
        data_setCurrentDriverName(newName);
    });
}

// כפתור "שמור שינויים" במודאל הגדרות חשבון - בכוונה לא משתמש ב-runWithDelay/morphButtonSuccess
// המשותפים (אייקון וי + "מתכווץ" לעיגול): מידות קבועות (מוקפאות ב-JS) לאורך כל האנימציה,
// ספינר כחול בזמן השמירה, מצב ירוק ללא אייקון בהצלחה, ואז סגירה חלקה של המודאל (closeModalAnimated הקיים)
function runAccountSaveAction(btnEl, performSave) {
    if (!btnEl) return;
    const originalHtml = btnEl.innerHTML;
    const rect = btnEl.getBoundingClientRect();
    btnEl.style.width = `${rect.width}px`;
    btnEl.style.height = `${rect.height}px`;
    btnEl.disabled = true;
    btnEl.innerHTML = '<span class="btn-inline-spinner"></span>';

    setTimeout(() => {
        performSave();
        btnEl.classList.add('btn-save-success');
        btnEl.textContent = 'נשמר בהצלחה';

        setTimeout(() => {
            closeModalAnimated(document.getElementById('modalAccountSettings'), 500, () => {
                btnEl.classList.remove('btn-save-success');
                btnEl.disabled = false;
                btnEl.innerHTML = originalHtml;
                btnEl.style.width = '';
                btnEl.style.height = '';
            });
        }, 700);
    }, BTN_DELAY_MS);
}

// שליחת בקשת הצטרפות לתחנה - יוצרת רשומת בקשה ממתינה לאישור התחנה (ללא תשלום בשלב זה),
// ומעדכנת את כפתור ה"הצטרף עכשיו" של אותה תחנה בלבד למצב ממתין. הבקשה נשלחת גם לשרת
// (POST /api/join-requests) כדי שתופיע במכשירים אחרים (למשל לוח הבקרה של המנהל בדסקטופ
// כשהבקשה נשלחה מהנייד) - ראו syncSharedStateFromServer. אם אין חיבור לשרת, נשמר מקומית בלבד.
async function requestJoinStation(stationId, stationName) {
    const data = loadAppData();
    const driverName = data.currentDriverName || 'נהג';
    const alreadyRequested = data.joinRequests.some(r => r.stationId === stationId && r.driverName === driverName && r.status !== 'rejected');
    if (alreadyRequested) return;

    let record = null;
    try {
        const res = await fetch('/api/join-requests', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ stationId, stationName, driverName })
        });
        const json = await res.json();
        if (json.success) record = json.request;
    } catch (err) {
        // אין חיבור לשרת - ממשיכים עם שמירה מקומית בלבד
    }

    if (!record) {
        const now = new Date();
        record = {
            id: 'join-' + Date.now(),
            stationId,
            stationName,
            driverName,
            status: 'pending',
            timestamp: now.toLocaleDateString('he-IL') + ' | ' + now.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' })
        };
    }

    data.joinRequests.push(record);
    saveAppData(data);
    renderDriverStations();
}

